const resp = $input.first().json;

if (resp.error) throw new Error('Gemini API error: ' + (resp.error.message || JSON.stringify(resp.error).slice(0, 300)));
if (resp.promptFeedback && resp.promptFeedback.blockReason) throw new Error('Gemini blocked the prompt: ' + resp.promptFeedback.blockReason);

const cand = (resp.candidates || [])[0];
if (!cand) throw new Error('Gemini returned no candidates.');
if (cand.finishReason && cand.finishReason !== 'STOP') {
  throw new Error('Gemini finishReason=' + cand.finishReason + ' (likely MAX_TOKENS - raise output budget or shorten prompt).');
}
const raw = (cand.content && cand.content.parts ? cand.content.parts : []).map(p => p.text || '').join('');
if (!raw.trim()) throw new Error('Gemini returned empty text.');

let data;
try {
  data = JSON.parse(raw.trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, ''));
} catch (e) {
  throw new Error('Gemini output was not valid JSON: ' + raw.slice(0, 300));
}

for (const f of ['post_title', 'wp_post_html', 'tg_summary']) {
  if (typeof data[f] !== 'string' || !data[f].trim()) throw new Error('Missing required Gemini field: ' + f);
}

// Telegram HTML sanitizer
let tg = String(data.tg_summary)
  .replace(/<br\s*\/?>/gi, '\n')   // FIX: <br>/<br/> -> real newline (Telegram HTML has no <br>)
  .replace(/&(?!(amp|lt|gt|quot|#\d+);)/gi, '&amp;')
  .replace(/<(?!\/?(?:b|i|u|s|a|code|pre)(?=[\s\/>]))/gi, '&lt;');
if (tg.length > 2000) {
  tg = tg.slice(0, 1990).replace(/<[^>]*$/, '').trimEnd() + '...';
}

const cfg = $('Pipeline Config').first().json;
const file = $('PDF Added to Drive Folder').first().json;
const plain = tg.replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();

return [{
  json: {
    sourceFileName: file.name || 'unknown.pdf',
    driveFileId: file.id || null,
    post_title: data.post_title.trim(),
    ticker: (data.ticker || '').trim(),
    broker: (data.broker || '').trim(),
    report_type: data.report_type || 'Other',
    wp_post_html: data.wp_post_html,
    tg_summary: tg,
    excerpt_plain: plain.slice(0, 240),
    categories: Array.isArray(data.categories) ? data.categories : [],
    tags: Array.isArray(data.tags) ? data.tags : [],
    wpBaseUrl: String(cfg.wpBaseUrl).replace(/\/+$/, ''),
    wpCategoryIds: cfg.wpCategoryIds || '',
    tgChannelId: cfg.tgChannelId
  }
}];

const wp = $input.first().json;
const p = $('Parse & Validate Gemini JSON').first().json;

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const title = esc(p.post_title);
const meta = [p.ticker, p.broker, p.report_type].filter(Boolean).map(esc).join(' | ');
const previewLink = p.wpBaseUrl + '/?p=' + wp.id + '&preview=true';

const message = [
  '<b>' + title + '</b>',
  meta ? '<i>' + meta + '</i>' : null,
  '',
  p.tg_summary,
  '',
  '<b>WP Draft #' + wp.id + '</b> - <a href="' + previewLink + '">Preview draft</a>',
  '<i>File: ' + esc(p.sourceFileName) + ' | status: ' + esc(wp.status) + '</i>'
].filter(x => x !== null).join('\n');

return [{ json: {
  channelId: p.tgChannelId,
  message: message,
  postId: wp.id,
  previewLink: previewLink,
  driveFileId: p.driveFileId
} }];

const e = $input.first().json || {};
const err = e.error || {};
const exec = e.execution || {};

let fileName = 'n/a';
let adminChatId = null;
try { fileName = $('PDF Added to Drive Folder').first().json.name || 'n/a'; } catch (_) {}
try { adminChatId = $('Pipeline Config').first().json.adminChatId; } catch (_) {}

const alertText = [
  '<b>SHIELD-PIPELINE failure</b>',
  '<b>File:</b> ' + fileName,
  '<b>Node:</b> ' + (exec.lastNodeExecuted || 'unknown'),
  '<b>Error:</b> ' + String(err.message || JSON.stringify(err).slice(0, 300) || 'unknown').slice(0, 600),
  '<b>Execution:</b> ' + (exec.url || 'n/a')
].join('\n');

return [{ json: { adminChatId: adminChatId, alertText: alertText } }];

const item = $input.first();

// Preferred: buffer via n8n helper (works even in filesystem binary mode)
let buffer = null;
try {
  buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
} catch (_) {}

// Fallback: base64 string straight off the binary object
if (!buffer || buffer.length === 0) {
  const b64 = item.binary?.data?.data;
  if (!b64) throw new Error('PDF binary not found in property "data" — check Download PDF node');
  buffer = Buffer.from(b64, 'base64');
}

if (buffer.length < 500) {
  throw new Error('PDF buffer suspiciously small (' + buffer.length + ' bytes) — download likely failed');
}

return [{
  json: {
    pdfBase64: buffer.toString('base64'),
    pdfBytes: buffer.length,
    pdfName: item.binary?.data?.fileName || 'unknown.pdf'
  }
}];
